CREATE PROCEDURE `sp_generate_test_users`(
    IN p_scenario VARCHAR(20),
    IN p_password VARCHAR(255)
)
BEGIN
    DECLARE v_total INT DEFAULT 0;
    DECLARE v_i INT DEFAULT 0;
    DECLARE v_user_id INT UNSIGNED;
    DECLARE v_status BIT(1);
    DECLARE v_country CHAR(2);
    DECLARE v_gender VARCHAR(30);
    DECLARE v_age INT;
    DECLARE v_birth_date DATE;
    DECLARE v_given_names VARCHAR(150);
    DECLARE v_family_names VARCHAR(150);
    DECLARE v_email VARCHAR(100);
    DECLARE v_nick VARCHAR(50);
    DECLARE v_unique VARCHAR(32);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_password IS NULL OR CHAR_LENGTH(p_password) < 8 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT =
            'La contraseña debe tener al menos 8 caracteres';
    END IF;

    CASE p_scenario
        WHEN 'escenario_1' THEN SET v_total = 500;
        WHEN 'escenario_2' THEN SET v_total = 2000;
        WHEN 'escenario_3' THEN SET v_total = 5000;
        ELSE
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT =
                'Usa escenario_1, escenario_2 o escenario_3';
    END CASE;

    START TRANSACTION;

    WHILE v_i < v_total DO
        SET v_i = v_i + 1;

        -- Estados: 4000 activos y 1000 inactivos
        -- en el escenario 3.
        IF p_scenario = 'escenario_3' AND v_i > 4000 THEN
            SET v_status = b'0';
        ELSE
            SET v_status = b'1';
        END IF;

        -- País.
        IF p_scenario = 'escenario_1' THEN
            SET v_country = 'US';
        ELSE
            SET v_country = ELT(
                1 + FLOOR(RAND() * 10),
                'MX', 'CA', 'GB', 'FR', 'DE',
                'ES', 'BR', 'JP', 'AU', 'IN'
            );
        END IF;

        -- Edad.
        IF p_scenario = 'escenario_2' THEN
            SET v_age = 19 + FLOOR(RAND() * 17);
        ELSE
            SET v_age = 18 + FLOOR(RAND() * 48);
        END IF;

        SET v_birth_date =
            DATE_SUB(CURDATE(), INTERVAL v_age YEAR)
            - INTERVAL FLOOR(RAND() * 365) DAY;

        -- Nombres variados.
        SET v_given_names = ELT(
            1 + FLOOR(RAND() * 30),
            'Carlos', 'Maria', 'Jose', 'Ana', 'Luis',
            'Sofia', 'Miguel', 'Lucia', 'Diego', 'Valeria',
            'Daniel', 'Gabriela', 'Alejandro', 'Camila',
            'Fernando', 'Isabella', 'Ricardo', 'Elena',
            'Andres', 'Natalia', 'James', 'Emily',
            'William', 'Olivia', 'Benjamin', 'Charlotte',
            'Noah', 'Amelia', 'Lucas', 'Emma'
        );

        -- Apellidos variados.
        SET v_family_names = ELT(
            1 + FLOOR(RAND() * 30),
            'Hernandez', 'Garcia', 'Martinez', 'Lopez',
            'Gonzalez', 'Rodriguez', 'Perez', 'Sanchez',
            'Ramirez', 'Torres', 'Flores', 'Rivera',
            'Gomez', 'Diaz', 'Cruz', 'Morales',
            'Reyes', 'Ortiz', 'Gutierrez', 'Castillo',
            'Smith', 'Johnson', 'Brown', 'Williams',
            'Jones', 'Miller', 'Davis', 'Wilson',
            'Anderson', 'Taylor'
        );

        SET v_gender = ELT(
            1 + FLOOR(RAND() * 3),
            'hombre', 'mujer', 'Prefiero no decirlo'
        );

        -- Identificador para evitar correos y nicks duplicados.
        SET v_unique = REPLACE(UUID(), '-', '');

        -- Correo formado con nombre y apellido.
        SET v_email = LOWER(CONCAT(
            v_given_names, '.', v_family_names, '.',
            LEFT(v_unique, 8), '[correo omitido]'
        ));

        -- Nick basado en el nombre y apellido.
        SET v_nick = LOWER(CONCAT(
            LEFT(v_given_names, 15), '_',
            LEFT(v_family_names, 15), '_',
            LEFT(v_unique, 8)
        ));

        -- Insertar cuenta.
        INSERT INTO db_users (
            email,
            nick,
            password,
            creation_date,
            last_update,
            last_login,
            status
        )
        VALUES (
            v_email,
            v_nick,
            MD5(p_password),
            CURRENT_TIMESTAMP,
            NULL,
            NULL,
            v_status
        );

        SET v_user_id = LAST_INSERT_ID();

        -- Insertar datos personales vinculados al usuario.
        INSERT INTO tb_people (
            user_ID,
            courtesy_title,
            given_names,
            family_names,
            birth_date,
            gender,
            country_code,
            phone,
            status,
            creation_date,
            last_update
        )
        VALUES (
            v_user_id,
            NULL,
            v_given_names,
            v_family_names,
            v_birth_date,
            v_gender,
            v_country,
            CONCAT(
                '+1 ',
                FLOOR(1000000000 + RAND() * 899999999)
            ),
            v_status,
            CURRENT_TIMESTAMP,
            CURRENT_TIMESTAMP
        );

    END WHILE;

    COMMIT;

    SELECT
        p_scenario AS escenario,
        v_total AS usuarios_solicitados,
        'Proceso completado' AS resultado;
END ;

CREATE PROCEDURE `sp_register_new_user`(
    IN p_email          VARCHAR(100),
    IN p_nick           VARCHAR(50),
    IN p_password       VARCHAR(100),
    IN p_courtesy_title VARCHAR(50),
    IN p_given_names    VARCHAR(150),
    IN p_family_names   VARCHAR(150),
    IN p_birth_date     DATE,
    IN p_gender         VARCHAR(30),
    IN p_country_code   VARCHAR(2),
    IN p_phone          VARCHAR(25)
)
    MODIFIES SQL DATA
BEGIN
    DECLARE v_db_user   VARCHAR(32);
    DECLARE v_has_role  INT DEFAULT 0;
    DECLARE v_count     INT DEFAULT 0;
    DECLARE v_user_id   INT UNSIGNED;
    DECLARE v_person_id BIGINT UNSIGNED;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    DECLARE EXIT HANDLER FOR 1062
    BEGIN
        ROLLBACK;
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El correo, el nick o la relación de persona ya se encuentran registrados';
    END;

    SET v_db_user = SUBSTRING_INDEX(USER(), '@', 1);

    -- Requiere permisos para consultar mysql.role_edges.
    SELECT COUNT(*)
      INTO v_has_role
      FROM mysql.role_edges AS re
     WHERE re.TO_USER = v_db_user
       AND re.TO_HOST = '%'
       AND re.FROM_HOST = '%'
       AND re.FROM_USER IN (
           'superadmin', 'admin', 'support', 'user_not_registered'
       );

    IF v_has_role = 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'Acceso denegado: rol no autorizado';
    END IF;

    SET p_email          = LOWER(TRIM(p_email));
    SET p_nick           = TRIM(p_nick);
    SET p_given_names    = TRIM(p_given_names);
    SET p_family_names   = NULLIF(TRIM(p_family_names), '');
    SET p_courtesy_title = NULLIF(TRIM(p_courtesy_title), '');
    SET p_gender         = COALESCE(NULLIF(TRIM(p_gender), ''), 'Prefiero no decirlo');
    SET p_country_code   = NULLIF(UPPER(TRIM(p_country_code)), '');
    SET p_phone          = NULLIF(TRIM(p_phone), '');

    IF p_email IS NULL OR p_email NOT REGEXP '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El correo electrónico es inválido';
    END IF;

    IF p_nick IS NULL OR CHAR_LENGTH(p_nick) < 3 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El nick debe tener al menos 3 caracteres';
    END IF;

    IF p_password IS NULL OR CHAR_LENGTH(p_password) < 8 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La contraseña debe tener al menos 8 caracteres';
    END IF;

    IF p_given_names IS NULL OR p_given_names = '' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El nombre es obligatorio';
    END IF;

    IF p_birth_date IS NOT NULL
       AND (p_birth_date > CURRENT_DATE OR p_birth_date < '1900-01-01') THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'La fecha de nacimiento es inválida';
    END IF;

    SET p_gender = CASE
        WHEN LOWER(p_gender) = 'hombre' THEN 'hombre'
        WHEN LOWER(p_gender) = 'mujer' THEN 'mujer'
        WHEN LOWER(p_gender) = 'prefiero no decirlo' THEN 'Prefiero no decirlo'
        ELSE p_gender
    END;

    IF p_gender NOT IN ('hombre', 'mujer', 'Prefiero no decirlo') THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El género debe ser Hombre, Mujer o Prefiero no decirlo';
    END IF;

    IF p_country_code IS NOT NULL AND p_country_code NOT REGEXP '^[A-Z]{2}$' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El código de país debe tener 2 letras (ISO)';
    END IF;

    IF p_phone IS NOT NULL AND p_phone NOT REGEXP '^[0-9+() -]{7,25}$' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El teléfono es inválido';
    END IF;

    SELECT COUNT(*) INTO v_count
      FROM `db_users`
     WHERE `email` = p_email;

    IF v_count > 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El correo electrónico ya se encuentra registrado';
    END IF;

    SELECT COUNT(*) INTO v_count
      FROM `db_users`
     WHERE `nick` = p_nick;

    IF v_count > 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El nick ya se encuentra en uso';
    END IF;

    START TRANSACTION;

    INSERT INTO `db_users` (`email`, `nick`, `password`)
    VALUES (p_email, p_nick, MD5(p_password));

    SET v_user_id = LAST_INSERT_ID();

    INSERT INTO `tb_people` (
        `user_ID`, `courtesy_title`, `given_names`, `family_names`,
        `birth_date`, `gender`, `country_code`, `phone`
    )
    VALUES (
        v_user_id, p_courtesy_title, p_given_names, p_family_names,
        p_birth_date, p_gender, p_country_code, p_phone
    );

    SET v_person_id = LAST_INSERT_ID();

    COMMIT;

    SELECT
        'Usuario y persona registrados correctamente' AS mensaje,
        v_user_id AS user_id,
        v_person_id AS person_id,
        p_email AS email,
        p_nick AS nick,
        v_db_user AS ejecutado_por,
        CURRENT_TIMESTAMP AS fecha_operacion;
END ;

CREATE PROCEDURE `sp_restore_product`(
    IN p_product_id INT UNSIGNED
)
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM tb_products
        WHERE ID = p_product_id
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El producto especificado no existe';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM tb_products
        WHERE ID = p_product_id
          AND status = b'1'
    ) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'El producto ya se encuentra activo';
    END IF;

    UPDATE tb_products
    SET status = b'1'
    WHERE ID = p_product_id;
END ;

CREATE PROCEDURE `sp_soft_delete_product`(
    IN p_product_id INT UNSIGNED
)
BEGIN

    
    IF NOT EXISTS (
        SELECT 1
        FROM tb_products
        WHERE ID = p_product_id
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El producto especificado no existe';
    END IF;

    
    IF EXISTS (
        SELECT 1
        FROM tb_products
        WHERE ID = p_product_id
            AND status = b'0'
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'El producto ya se encuentra eliminado';
    END IF;

    
    UPDATE tb_products
    SET status = b'0'
    WHERE ID = p_product_id;

END ;
